// TH14 synthetic appearance aliases (see transcribe/th14/touhou-bullets.ecl).
// Native type 6 -> TH14_RING_BALL; color stays the source color slot.
const TH14_RING_BALL: int = 448;

// TH14 v1.00b Extra 道中第 2 波（st07.ecl MainSub01 669-688）。
// 12 只 GirlB01 分五组出生；子敌依赖 GirlB01 276-286 / GirlB01_at 288-304 /
// GirlB01_at2 306-333。Extra 仅 rank4，取源 O 位；at2 的 B=32 轮。

const TIME_LIMIT: int = 2624;
const OPENING_BUFFER: int = 120;

const GIRL_HP: int = 400;      // 671-686 enmCreate hp=400
const GIRL_SCORE: int = 1000;  // 671-686 score=1000

// GirlB01_at 288-304；mirror 来自 enmCreateM 的子镜像位（304 的 M 变体）。
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                 // 290 setHurtbox(24,24)：普通圆取第一值×0.5
    set_hitbox(8fx);                   // 291 setHitbox(16,16) 同上
    move_vel(0, 90deg, 3fx, EASE_LINEAR);      // 292 moveVel(pi/2, 3.0)
    // 293 moveVelTime(80, mode1=quad-in, 1.7671459 rad=101.25deg, 0.0)
    // 297 moveVelTime(60, mode0=linear, 2.9452431 rad=168.75deg, 1.0)
    var turn1: angle = 101.25deg;
    var turn2: angle = 168.75deg;
    if mirror != 0 {
        turn1 = 78.75deg;              // 镜像 x→-x：方向取 pi-θ
        turn2 = 11.25deg;
    }
    move_vel(80, turn1, 0fx, EASE_QUAD_IN);
    wait(60);                          // 294
    spawn girl_volleys();              // 295 @GirlB01_at2() async
    wait(120);                         // 296
    move_vel(60, turn2, 1fx, EASE_LINEAR);
    loop { wait(1000); }               // 299-302 等待循环
}

// GirlB01_at2 306-333：32 轮；每轮 4 次 3 路扇形，发后等 5 帧，轮末再等 40 帧。
async sub girl_volleys() {
    var rounds: int = 0;
    while rounds < 32 {                // 317/331 diffI 在 Extra 取 32
        var shot: int = 0;
        while shot < 4 {               // 321 $C = 4
            var jitter: int = rand(1024) - 512;   // 324 RANDRAD/64 → ±pi/64 rad
            var base: angle = aim_player();       // 每波一次自机角（原 etOn 时解析）
            var mid: angle = base + (jitter as angle);
            var left: angle = mid - 10deg;        // 324 第二角 0.17453292 rad
            var right: angle = mid + 10deg;
            // 315 etExSet type=2(a=1) ANIM：进入保留 position -= 4*speed
            _ = fire(TH14_RING_BALL, 2, $self_x - 12fx * cos(mid), $self_y - 12fx * sin(mid), 3fx, mid, none, none);
            _ = fire(TH14_RING_BALL, 2, $self_x - 12fx * cos(left), $self_y - 12fx * sin(left), 3fx, left, none, none);
            _ = fire(TH14_RING_BALL, 2, $self_x - 12fx * cos(right), $self_y - 12fx * sin(right), 3fx, right, none, none);
            wait(5);                   // 326
            shot = shot + 1;
        }
        wait(40);                      // 329
        rounds = rounds + 1;
    }
}

// MainSub01 669-688：0/50/100/150/200 分组创建；M 变体给子镜像位。
async sub wave() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(0));
    _ = spawn_enemy(-160fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(0));
    _ = spawn_enemy(160fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(1));
    wait(50);
    _ = spawn_enemy(-32fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(0));
    _ = spawn_enemy(32fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(0));
    wait(50);
    _ = spawn_enemy(-64fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(1));
    _ = spawn_enemy(64fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(1));
    wait(50);
    _ = spawn_enemy(-128fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(0));
    _ = spawn_enemy(128fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(1));
    wait(50);
    _ = spawn_enemy(0fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(0));
    _ = spawn_enemy(-160fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(1));
    _ = spawn_enemy(160fx, -32fx, GIRL_HP, 0, GIRL_SCORE, 0, girl(0));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
